 @attribute [Authorize(Roles = "Dispatcher")]
 @inject IShipmentService ShipmentService

 <PageTitle>Dispatch Dashboard</PageTitle>

 <div class="container-fluid mt-4">
     <h2>Dispatch Dashboard</h2>

     <div class="row mb-3">
         <div class="col-md-4">
             <input type="text" class="form-control" placeholder="Filter by tracking # or destination..."
                    @bind="filterText" @bind:event="oninput" />
         </div>
     </div>

     @if (isLoading)
     {
         <div class="spinner-border text-primary" role="status">
             <span class="visually-hidden">Loading...</span>
         </div>
     }
     else if (shipments is not null)
     {
         <div class="table-responsive">
             <table class="table table-striped table-hover">
                 <thead class="table-dark">
                     <tr>
                         <th>Tracking #</th>
                         <th>Origin</th>
                         <th>Destination</th>
                         <th>Status</th>
                         <th>Shipped Date</th>
                         <th>Est. Delivery</th>
                         <th>Update Status</th>
                     </tr>
                 </thead>
                 <tbody>
                     @foreach (var s in FilteredShipments)
                     {
                         <tr>
                             <td><strong>@s.TrackingNumber</strong></td>
                             <td>@s.Origin</td>
                             <td>@s.Destination</td>
                             <td><span class="badge @GetStatusBadgeClass(s.Status)">@GetStatusLabel(s.Status)</span></td>
                             <td>@s.ShippedDate.ToString("MMM dd, yyyy")</td>
                             <td>@s.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                             <td>
                                 <select class="form-select form-select-sm" value="@((int)s.Status)"
                                         @onchange="(e) => OnStatusChanged(s, e)">
                                     @foreach (ShipmentStatus status in Enum.GetValues<ShipmentStatus>())
                                     {
                                         <option value="@((int)status)">@GetStatusLabel(status)</option>
                                     }
                                 </select>
                             </td>
                         </tr>
                     }
                 </tbody>
             </table>
         </div>

         @if (!FilteredShipments.Any())
         {
             <div class="alert alert-info">No shipments match your filter.</div>
         }
     }
 </div>

 @code {
     private List<Shipment>? shipments;
     private string filterText = string.Empty;
     private bool isLoading = true;

     private IEnumerable<Shipment> FilteredShipments =>
         shipments?.Where(s =>
             string.IsNullOrWhiteSpace(filterText) ||
             s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
             s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase))
         ?? Enumerable.Empty<Shipment>();

     protected override async Task OnInitializedAsync()
     {
         try
         {
             shipments = await ShipmentService.GetAllShipmentsAsync();
         }
         catch
         {
             shipments = new();
         }
         finally
         {
             isLoading = false;
         }
     }

     private async Task OnStatusChanged(Shipment shipment, ChangeEventArgs e)
     {
         if (int.TryParse(e.Value?.ToString(), out var statusInt))
         {
             var newStatus = (ShipmentStatus)statusInt;
             await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
             shipment.Status = newStatus;
         }
     }

     private static string GetStatusLabel(ShipmentStatus status) => status switch
     {
         ShipmentStatus.Pending => "Pending",
         ShipmentStatus.InTransit => "In Transit",
         ShipmentStatus.OutForDelivery => "Out for Delivery",
         ShipmentStatus.Delivered => "Delivered",
         ShipmentStatus.Delayed => "Delayed",
         _ => "Unknown"
     };

     private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
     {
         ShipmentStatus.Pending => "bg-secondary",
         ShipmentStatus.InTransit => "bg-info text-dark",
         ShipmentStatus.OutForDelivery => "bg-warning text-dark",
         ShipmentStatus.Delivered => "bg-success",
         ShipmentStatus.Delayed => "bg-danger",
         _ => "bg-secondary"
     };
 }

